params.fn:
function(ctx){
  var cid=String(ctx.commentId||'').trim();
  var uid=String(ctx.userId||'').trim();
  var mode='comment';
  if(cid){mode='reply_id';}
  else if(uid){mode='reply_user';}
  window.__qiworkComment={
    mode:mode,
    commentId:cid,
    userId:uid,
    count:document.querySelectorAll('.parent-comment').length,
    text:String(ctx.content||'')
  };
  return {mode:mode,count:window.__qiworkComment.count,commentId:cid,userId:uid};
}

function(ctx){
  var uid=String(ctx.userId||'').trim();
  if(!uid){return {found:false};}
  var container=document.querySelector('.comments-container');
  if(container){container.scrollIntoView({block:'start'});}
  var attempts=0;
  var foundEl=null;
  while(attempts<40&&!foundEl){
    attempts++;
    var nodes=document.querySelectorAll('.parent-comment,.comment-item,.comment');
    for(var i=0;i<nodes.length;i++){
      var el=nodes[i];
      if(el.querySelector('[data-user-id="'+uid+'"]')){foundEl=el;break;}
    }
    if(foundEl){break;}
    window.scrollBy(0,Math.floor(window.innerHeight*0.75));
  }
  if(!foundEl){return {found:false,attempts:attempts};}
  foundEl.scrollIntoView({block:'center'});
  var id=foundEl.id||'';
  if(id.indexOf('comment-')===0){window.__qiworkComment.commentId=id.slice(8);}
  var reply=foundEl.querySelector('.right .interactions .reply,.interactions .reply');
  if(reply){reply.click();}
  return {found:true,attempts:attempts,commentId:window.__qiworkComment.commentId||''};
}

params.expression:
(function(){
  var st=window.__qiworkComment;
  if(!st)return false;
  if(st.mode==='comment'){
    return document.querySelectorAll('.parent-comment').length > st.count;
  }
  var node=document.querySelector('#comment-'+st.commentId);
  if(!node)return false;
  if((node.innerText||'').indexOf(st.text)<0)return false;
  var field=document.querySelector('div.input-box div.content-edit p.content-input');
  var still=field&&(field.innerText||'').indexOf(st.text)>=0;
  return !still;
})()

params.fn:
function(){
  var st=window.__qiworkComment||{};
  return {
    mode:st.mode||'',
    comment_id:st.commentId||'',
    user_id:st.userId||'',
    comments_before:st.count||0,
    comments_after:document.querySelectorAll('.parent-comment').length,
    text:st.text||''
  };
}
